class DocumentsManager {
    constructor() {
        this.currentPage = 1;
        this.itemsPerPage = 10;
        this.collection = '';
        this.documents = [];
        this.lastDoc = null;
        this.hasMore = false;
        var user = sessionStorage.getItem("user");
        if(user==null) {goto(""); return;}
        user = JSON.parse(user);
        if(user.role!="ADMIN"){goto(""); return;}
        this.initialize();
        this.listen();
    }

    initialize() { 
        console.log("DocumentsManager:initialize");
        this.tableBody = document.getElementById('documentsTableBody');
        this.collectionInput = document.getElementById('collectionInput');
        this.searchKeyInput = document.getElementById('searchKeyInput');
        this.searchValueInput = document.getElementById('searchValueInput');
        this.searchBtn = document.getElementById('searchBtn');
        this.addDocumentBtn = document.getElementById('addDocumentBtn');
        this.prevPageBtn = document.getElementById('prevPage');
        this.nextPageBtn = document.getElementById('nextPage');
        this.currentPageSpan = document.getElementById('currentPage');
        this.totalPagesSpan = document.getElementById('totalPages');
    }

    listen() {
        console.log("DocumentsManager:listen");
        this.collectionInput.addEventListener('keydown', (event) => {
            if (event.key === 'Enter') this.loadCollection();
        });
        this.searchKeyInput.addEventListener('keydown', (event) => {
            if (event.key === 'Enter') this.loadCollection();
        });
        this.searchValueInput.addEventListener('keydown', (event) => {
            if (event.key === 'Enter') this.loadCollection();
        });
        this.searchBtn.addEventListener('click', () => this.loadCollection());
        this.addDocumentBtn.addEventListener('click', () => this.showAddModal());
        this.prevPageBtn.addEventListener('click', () => this.changePage(-1));
        this.nextPageBtn.addEventListener('click', () => this.changePage(1));
    }

    getReadOptions(extra = {}) {
        const options = { size: this.itemsPerPage, ...extra };
        const searchKey = this.searchKeyInput?.value?.trim();
        const searchValue = this.searchValueInput?.value?.trim();

        if (searchKey && searchValue !== '') {
            options.search = { key: searchKey, value: searchValue };
        }

        return options;
    }

    async loadCollection() {
        this.collection = this.collectionInput.value.trim().toLowerCase();
        if (!this.collection) {
            this.showError('Please enter a collection name');
            return;
        }

        Loader.show();
        try {
            const result = await Firebase.read(this.collection, this.getReadOptions());
            this.documents = result.data;
            this.lastDoc = result.lastDoc;
            this.hasMore = result.hasMore;
            this.currentPage = 1;
            this.updatePagination();
            this.renderDocuments();
        } catch (error) {
            console.error('Error loading collection:', error);
            this.showError('Failed to load documents');
        } finally {
            Loader.hide();
        }
    }

    async changePage(delta) {
        if (delta > 0 && !this.hasMore) return;
        if (delta < 0 && this.currentPage === 1) return;

        Loader.show();
        try {
            if (delta > 0) {
                const result = await Firebase.read(this.collection, this.getReadOptions({
                    lastDoc: this.lastDoc
                }));
                this.documents = result.data;
                this.lastDoc = result.lastDoc;
                this.hasMore = result.hasMore;
                this.currentPage++;
            } else {
                const result = await Firebase.read(this.collection, this.getReadOptions());
                this.documents = result.data;
                this.lastDoc = result.lastDoc;
                this.hasMore = result.hasMore;
                this.currentPage = 1;
            }
            this.updatePagination();
            this.renderDocuments();
        } catch (error) {
            console.error('Error changing page:', error);
            this.showError('Failed to load documents');
        } finally {
            Loader.hide();
        }
    }

    updatePagination() {
        this.currentPageSpan.textContent = this.currentPage;
        this.totalPagesSpan.textContent = this.hasMore ? '...' : this.currentPage;
        this.prevPageBtn.disabled = this.currentPage === 1;
        this.nextPageBtn.disabled = !this.hasMore;
    }

    renderDocuments() {
        if (!Array.isArray(this.documents)) {
            console.error('Documents is not an array:', this.documents);
            this.documents = [];
        }

        this.tableBody.innerHTML = this.documents.map(doc => {
            const docName = doc.name || doc.id || 'Unnamed Document';
            return `
                <tr>
                    <td>${docName}</td>
                    <td>
                        <button class="action-btn edit" onclick="documentsManager.editDocument('${doc.id}')">
                            <span class="material-icons">edit</span>
                        </button>
                        <button class="action-btn advanced-edit" onclick="documentsManager.editDocumentAdvanced('${doc.id}')" title="Edit a field" aria-label="Edit a field">
                            <span class="material-icons">tune</span>
                        </button>
                        <button class="action-btn delete" onclick="documentsManager.deleteDocument('${doc.id}')">
                            <span class="material-icons">delete</span>
                        </button>
                    </td>
                </tr>
            `;
        }).join('');
    }

    async deleteDocument(docId) {
        if (confirm('Are you sure you want to delete this document?')) {
            try {
                Loader.show();
                await Firebase.delete(this.collection, docId);
                this.documents = this.documents.filter(doc => doc.id !== docId);
                this.renderDocuments();
            } catch (error) {
                console.error('Error deleting document:', error);
                this.showError('Failed to delete document');
            } finally {
                Loader.hide();
            }
        }
    }

    async editDocument(docId) {
        try {
            Loader.show();
            const result = await Firebase.read(this.collection, { docId });
            const doc = result.data && result.data[0];
            if (!doc) {
                this.showError('Document not found');
                Loader.hide();
                return;
            }
            const { id, ...docContent } = doc;
            const textarea = document.getElementById('editDocumentTextarea');
            textarea.value = JSON.stringify(docContent, null, 2);
            const title = document.getElementById('editDocumentModalLabel');
            if (title) title.textContent = `EDIT ${docId}`;
            this._editingDocId = docId;
            this.showEditModal();
        } catch (error) {
            console.error('Error loading document for edit:', error);
            this.showError('Failed to load document');
        } finally {
            Loader.hide();
        }
    }

    async editDocumentAdvanced(docId) {
        try {
            Loader.show();
            const result = await Firebase.read(this.collection, { docId });
            const doc = result.data && result.data[0];
            if (!doc) {
                this.showError('Document not found');
                return;
            }
            const { id, ...docContent } = doc;
            this._advancedEditingDoc = docContent;
            this._advancedEditingDocId = docId;
            this.resetAdvancedEditor();
            const title = document.getElementById('editDocAdvancedModalLabel');
            if (title) title.textContent = `EDIT FIELD ${docId}`;
            this.showAdvancedEditModal();
        } catch (error) {
            console.error('Error loading document for advanced edit:', error);
            this.showError('Failed to load document');
        } finally {
            Loader.hide();
        }
    }

    resetAdvancedEditor() {
        this._advancedPath = [];
        const selectors = document.getElementById('advancedEditSelectors');
        if (selectors) selectors.innerHTML = '';
        this.updateAdvancedEditor();
    }

    updateAdvancedEditor() {
        const selectors = document.getElementById('advancedEditSelectors');
        const valueContainer = document.getElementById('advancedEditValueContainer');
        const valueInput = document.getElementById('advancedEditValue');
        const pathLabel = document.getElementById('advancedEditPath');
        const saveButton = document.getElementById('saveAdvancedEditBtn');
        if (!selectors || !this._advancedEditingDoc) return;

        const selectedValue = this._advancedPath.reduce((value, key) => value?.[key], this._advancedEditingDoc);
        const canEdit = ['string', 'number', 'boolean'].includes(typeof selectedValue);
        pathLabel.textContent = this._advancedPath.length
            ? this._advancedPath.map(key => typeof key === 'number' ? `[${key}]` : key).join('.')
            : 'Select a field to edit';
        if (valueContainer) valueContainer.style.display = canEdit ? 'flex' : 'none';
        if (saveButton) saveButton.disabled = !canEdit;
        if (canEdit && valueInput && document.activeElement !== valueInput) {
            valueInput.type = typeof selectedValue === 'boolean' ? 'checkbox' : 'text';
            if (valueInput.type === 'checkbox') valueInput.checked = selectedValue;
            else valueInput.value = selectedValue;
        }

        while (selectors.children.length > this._advancedPath.length) selectors.lastElementChild.remove();
        let currentValue = this._advancedEditingDoc;
        for (let level = 0; level <= this._advancedPath.length; level++) {
            if (level < this._advancedPath.length) {
                currentValue = currentValue[this._advancedPath[level]];
                continue;
            }
            if (currentValue === null || typeof currentValue !== 'object') break;
            const select = document.createElement('select');
            select.className = 'modal-input advanced-edit-select';
            const entries = Array.isArray(currentValue)
                ? currentValue.map((item, index) => [index, `Index ${index}`])
                : Object.keys(currentValue).map(key => [key, key]);
            const placeholder = document.createElement('option');
            placeholder.value = '';
            placeholder.textContent = 'Select a field';
            select.appendChild(placeholder);
            entries.forEach(([key, label]) => {
                const option = document.createElement('option');
                option.value = key;
                option.textContent = label;
                select.appendChild(option);
            });
            select.addEventListener('change', () => {
                const selectedKey = select.value;
                this._advancedPath = this._advancedPath.slice(0, level);
                if (selectedKey !== '') this._advancedPath.push(Array.isArray(currentValue) ? Number(selectedKey) : selectedKey);
                this.updateAdvancedEditor();
            });
            selectors.appendChild(select);
            break;
        }
    }

    showAdvancedEditModal() {
        this.hideEditModal();
        this.hideAddModal();
        const modal = document.getElementById('editDocAdvancedModal');
        const backdrop = document.getElementById('advancedEditModalBackdrop');
        if (!modal || !backdrop) return;
        modal.classList.add('show');
        modal.style.display = 'block';
        modal.removeAttribute('inert');
        modal.removeAttribute('aria-hidden');
        backdrop.classList.add('show');
        backdrop.style.display = 'block';
    }

    hideAdvancedEditModal() {
        const modal = document.getElementById('editDocAdvancedModal');
        const backdrop = document.getElementById('advancedEditModalBackdrop');
        if (!modal || !backdrop) return;
        modal.classList.remove('show');
        modal.style.display = 'none';
        modal.setAttribute('inert', '');
        modal.setAttribute('aria-hidden', 'true');
        backdrop.classList.remove('show');
        backdrop.style.display = 'none';
    }

    buildAdvancedPatch(value) {
        if (!this._advancedPath.length) return {};

        const clone = item => {
            if (Array.isArray(item)) return item.map(clone);
            if (item && typeof item === 'object' &&
                (Object.getPrototypeOf(item) === Object.prototype || Object.getPrototypeOf(item) === null)) {
                return Object.fromEntries(Object.entries(item).map(([key, child]) => [key, clone(child)]));
            }
            return item;
        };

        const documentCopy = clone(this._advancedEditingDoc);
        let target = documentCopy;
        for (let index = 0; index < this._advancedPath.length - 1; index++) {
            target = target[this._advancedPath[index]];
        }
        target[this._advancedPath[this._advancedPath.length - 1]] = value;

        return { [this._advancedPath[0]]: documentCopy[this._advancedPath[0]] };
    }

    async saveAdvancedEdit() {
        const currentValue = this._advancedPath.reduce((value, key) => value?.[key], this._advancedEditingDoc);
        const valueInput = document.getElementById('advancedEditValue');
        let value;
        if (typeof currentValue === 'boolean') value = valueInput.checked;
        else if (typeof currentValue === 'number') value = Number(valueInput.value);
        else value = valueInput.value;
        if (typeof currentValue === 'number' && (valueInput.value.trim() === '' || Number.isNaN(value))) {
            alert('Please enter a valid number.');
            return;
        }
        Loader.show();
        try {
            await Firebase.write(this.collection, this._advancedEditingDocId, this.buildAdvancedPatch(value));
            this.hideAdvancedEditModal();
            await this.loadCollection();
        } catch (error) {
            console.error('Error updating document field:', error);
            alert('Failed to update document field.');
        } finally {
            Loader.hide();
        }
    }

    showEditModal() {
        this.hideAdvancedEditModal();
        this.hideAddModal();
        const modal = document.getElementById('editDocumentModal');
        const backdrop = document.getElementById('editModalBackdrop');
        if (!modal || !backdrop) return;
        modal.classList.add('show');
        modal.style.display = 'block';
        modal.removeAttribute('inert');
        modal.removeAttribute('aria-hidden');
        const textarea = document.getElementById('editDocumentTextarea');
        if (textarea) textarea.focus();
        backdrop.classList.add('show');
        backdrop.style.display = 'block';
    }

    hideEditModal() {
        const modal = document.getElementById('editDocumentModal');
        const backdrop = document.getElementById('editModalBackdrop');
        if (!modal || !backdrop) return;
        modal.classList.remove('show');
        modal.style.display = 'none';
        modal.setAttribute('inert', '');
        modal.setAttribute('aria-hidden', 'true');
        document.body.focus();
        backdrop.classList.remove('show');
        backdrop.style.display = 'none';
    }

    showAiEnrichModal() {
        const editTextarea = document.getElementById('editDocumentTextarea');
        const modal = document.getElementById('aiEnrichModal');
        const backdrop = document.getElementById('aiEnrichModalBackdrop');
        const contentTextarea = document.getElementById('aiEnrichTextarea');
        const contextInput = document.getElementById('aiEnrichContextInput');
        const updateButton = document.getElementById('updateAiEnrichBtn');
        const status = document.getElementById('aiEnrichStatus');
        if (!editTextarea || !modal || !backdrop) return;

        try {
            JSON.parse(editTextarea.value);
        } catch (error) {
            alert('Please enter valid JSON before enriching the document.');
            return;
        }

        this.hideEditModal();
        if (contentTextarea) contentTextarea.value = '';
        if (contextInput && !contextInput.value) contextInput.value = 'Enrich this JSON with useful, complete content.';
        if (updateButton) updateButton.disabled = true;
        if (status) status.textContent = 'Add an enrichment request and generate a draft.';
        document.getElementById('aiEnrichModel').textContent = 'Not generated';
        document.getElementById('aiEnrichTokens').textContent = 'Not generated';
        document.getElementById('aiEnrichTokensLeft').textContent = 'Not generated';
        modal.classList.add('show');
        modal.style.display = 'block';
        modal.removeAttribute('inert');
        modal.removeAttribute('aria-hidden');
        backdrop.classList.add('show');
        backdrop.style.display = 'block';
        if (contextInput) contextInput.focus();
    }

    hideAiEnrichModal() {
        const modal = document.getElementById('aiEnrichModal');
        const backdrop = document.getElementById('aiEnrichModalBackdrop');
        if (!modal || !backdrop) return;
        modal.classList.remove('show');
        modal.style.display = 'none';
        modal.setAttribute('inert', '');
        modal.setAttribute('aria-hidden', 'true');
        backdrop.classList.remove('show');
        backdrop.style.display = 'none';
    }

    async generateAiEnrichment() {
        const editTextarea = document.getElementById('editDocumentTextarea');
        const contextInput = document.getElementById('aiEnrichContextInput');
        const contentTextarea = document.getElementById('aiEnrichTextarea');
        const updateButton = document.getElementById('updateAiEnrichBtn');
        const status = document.getElementById('aiEnrichStatus');
        let content;

        try {
            content = JSON.parse(editTextarea.value);
        } catch (error) {
            alert('Invalid JSON!');
            return;
        }

        const context = contextInput.value.trim();
        if (!context) {
            alert('Please describe how the JSON should be enriched.');
            contextInput.focus();
            return;
        }

        if (updateButton) updateButton.disabled = true;
        if (status) status.textContent = 'Generating enriched JSON...';
        Loader.show();
        try {
            const response = await fetch('https://api.openlib.in/json/enrich', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ context, content })
            });
            const result = await response.json();
            if (!response.ok || result.success !== true) {
                throw new Error(result.error || 'Enrichment request failed.');
            }

            const enrichedContent = result.content;
            if (enrichedContent === undefined || enrichedContent === null) {
                throw new Error('The enrichment API returned no updated content.');
            }

            let parsedContent = enrichedContent;
            if (typeof parsedContent === 'string') {
                parsedContent = parsedContent.replace(/^```(?:json)?\s*|\s*```$/g, '').trim();
                parsedContent = JSON.parse(parsedContent);
            }
            contentTextarea.value = JSON.stringify(parsedContent, null, 2);
            document.getElementById('aiEnrichModel').textContent = result.model;
            document.getElementById('aiEnrichTokens').textContent = result.tokensUsed;
            document.getElementById('aiEnrichTokensLeft').textContent = result.tokensLeft;
            if (status) status.textContent = 'Review the enriched JSON, then update the document.';
            if (updateButton) updateButton.disabled = false;
        } catch (error) {
            console.error('Error enriching document:', error);
            if (status) status.textContent = error.message || 'Failed to enrich document.';
            alert(error.message || 'Failed to enrich document.');
        } finally {
            Loader.hide();
        }
    }

    async updateEnrichedDocument() {
        const contentTextarea = document.getElementById('aiEnrichTextarea');
        let json;
        try {
            json = JSON.parse(contentTextarea.value);
        } catch (error) {
            alert('Invalid enriched JSON!');
            return;
        }
        if (!this._editingDocId || !this.collection) {
            alert('Missing document or collection info.');
            return;
        }

        Loader.show();
        try {
            await Firebase.write(this.collection, this._editingDocId, json);
            this.hideAiEnrichModal();
            await this.loadCollection();
        } catch (error) {
            console.error('Error updating enriched document:', error);
            alert('Failed to update document.');
        } finally {
            Loader.hide();
        }
    }

    showAddModal() {
        this.hideEditModal();
        this.hideAdvancedEditModal();
        const modal = document.getElementById('addDocumentModal');
        const backdrop = document.getElementById('addModalBackdrop');
        if (!modal || !backdrop) return;
        const collectionInput = document.getElementById('addCollectionInput');
        const docIdInput = document.getElementById('addDocumentIdInput');
        const textarea = document.getElementById('addDocumentTextarea');
        if (collectionInput) collectionInput.value = this.collection || '';
        if (docIdInput) docIdInput.value = '';
        if (textarea) textarea.value = '{\n  \"name\": \"example\"\n}';
        modal.classList.add('show');
        modal.style.display = 'block';
        modal.removeAttribute('inert');
        modal.removeAttribute('aria-hidden');
        if (collectionInput) collectionInput.focus();
        backdrop.classList.add('show');
        backdrop.style.display = 'block';
    }

    hideAddModal() {
        const modal = document.getElementById('addDocumentModal');
        const backdrop = document.getElementById('addModalBackdrop');
        if (!modal || !backdrop) return;
        modal.classList.remove('show');
        modal.style.display = 'none';
        modal.setAttribute('inert', '');
        modal.setAttribute('aria-hidden', 'true');
        document.body.focus();
        backdrop.classList.remove('show');
        backdrop.style.display = 'none';
    }

    async saveNewDocument() {
        const collectionInput = document.getElementById('addCollectionInput');
        const docIdInput = document.getElementById('addDocumentIdInput');
        const textarea = document.getElementById('addDocumentTextarea');

        const collection = collectionInput?.value?.trim().toLowerCase();
        const docId = docIdInput?.value?.trim();
        let json;

        if (!collection || !docId) {
            alert('Please provide a collection name and document ID.');
            return;
        }

        try {
            json = JSON.parse(textarea.value);
        } catch (error) {
            alert('Invalid JSON!');
            return;
        }

        Loader.show();
        try {
            await Firebase.write(collection, docId, json);
            this.collectionInput.value = collection;
            this.hideAddModal();
            await this.loadCollection();
        } catch (error) {
            console.error('Error creating document:', error);
            alert('Failed to save document.');
        } finally {
            Loader.hide();
        }
    }

    showError(message) {
        console.error(message);
    }
}

window.documentsManager = new DocumentsManager();

load = function() {
    const updateBtn = document.getElementById('updateDocumentBtn');
    const closeEditBtn = document.getElementById('closeEditModalBtn');
    const cancelEditBtn = document.getElementById('cancelEditModalBtn');
    const editBackdrop = document.getElementById('editModalBackdrop');
    const saveAdvancedEditBtn = document.getElementById('saveAdvancedEditBtn');
    const closeAdvancedEditBtn = document.getElementById('closeAdvancedEditModalBtn');
    const cancelAdvancedEditBtn = document.getElementById('cancelAdvancedEditModalBtn');
    const advancedEditBackdrop = document.getElementById('advancedEditModalBackdrop');
    const saveAddBtn = document.getElementById('saveAddDocumentBtn');
    const closeAddBtn = document.getElementById('closeAddModalBtn');
    const cancelAddBtn = document.getElementById('cancelAddModalBtn');
    const addBackdrop = document.getElementById('addModalBackdrop');
    const openAiEnrichBtn = document.getElementById('openAiEnrichModalBtn');
    const closeAiEnrichBtn = document.getElementById('closeAiEnrichModalBtn');
    const cancelAiEnrichBtn = document.getElementById('cancelAiEnrichModalBtn');
    const generateAiEnrichBtn = document.getElementById('generateAiEnrichBtn');
    const updateAiEnrichBtn = document.getElementById('updateAiEnrichBtn');
    const aiEnrichBackdrop = document.getElementById('aiEnrichModalBackdrop');

    if (updateBtn) {
        updateBtn.onclick = async () => {
            const textarea = document.getElementById('editDocumentTextarea');
            let json;
            try {
                json = JSON.parse(textarea.value);
            } catch (e) {
                alert('Invalid JSON!');
                return;
            }
            if (!documentsManager._editingDocId || !documentsManager.collection) {
                alert('Missing document or collection info.');
                return;
            }
            Loader.show();
            try {
                await Firebase.write(documentsManager.collection, documentsManager._editingDocId, json);
                documentsManager.hideEditModal();
                await documentsManager.loadCollection();
            } catch (err) {
                alert('Failed to update document.');
                console.error(err);
            } finally {
                Loader.hide();
            }
        };
    }

    if (saveAddBtn) {
        saveAddBtn.onclick = () => documentsManager.saveNewDocument();
    }

    const closeEditModal = () => documentsManager.hideEditModal();
    const closeAddModal = () => documentsManager.hideAddModal();

    if (closeEditBtn) closeEditBtn.onclick = closeEditModal;
    if (cancelEditBtn) cancelEditBtn.onclick = closeEditModal;
    if (editBackdrop) editBackdrop.onclick = closeEditModal;
    if (saveAdvancedEditBtn) saveAdvancedEditBtn.onclick = () => documentsManager.saveAdvancedEdit();
    if (closeAdvancedEditBtn) closeAdvancedEditBtn.onclick = () => documentsManager.hideAdvancedEditModal();
    if (cancelAdvancedEditBtn) cancelAdvancedEditBtn.onclick = () => documentsManager.hideAdvancedEditModal();
    if (advancedEditBackdrop) advancedEditBackdrop.onclick = () => documentsManager.hideAdvancedEditModal();
    if (closeAddBtn) closeAddBtn.onclick = closeAddModal;
    if (cancelAddBtn) cancelAddBtn.onclick = closeAddModal;
    if (addBackdrop) addBackdrop.onclick = closeAddModal;
    if (openAiEnrichBtn) openAiEnrichBtn.onclick = () => documentsManager.showAiEnrichModal();
    if (closeAiEnrichBtn) closeAiEnrichBtn.onclick = () => {
        documentsManager.hideAiEnrichModal();
        documentsManager.showEditModal();
    };
    if (cancelAiEnrichBtn) cancelAiEnrichBtn.onclick = () => {
        documentsManager.hideAiEnrichModal();
        documentsManager.showEditModal();
    };
    if (generateAiEnrichBtn) generateAiEnrichBtn.onclick = () => documentsManager.generateAiEnrichment();
    if (updateAiEnrichBtn) updateAiEnrichBtn.onclick = () => documentsManager.updateEnrichedDocument();
    if (aiEnrichBackdrop) aiEnrichBackdrop.onclick = () => {
        documentsManager.hideAiEnrichModal();
        documentsManager.showEditModal();
    };

    document.addEventListener('keydown', (event) => {
        if (event.key === 'Escape') {
            documentsManager.hideEditModal();
            documentsManager.hideAiEnrichModal();
            documentsManager.hideAdvancedEditModal();
            documentsManager.hideAddModal();
        }
    });
};

load();

components.style:
.documents-container { padding: 1rem; display: flex; justify-content: center; align-items: flex-start; min-height: 100vh; background: var(--color-page); }
.documents-content { text-align: center; width: 100%; max-width: 1200px; padding: clamp(1rem, 3vw, 2rem); background: var(--color-surface); border: 1px solid var(--color-border); border-radius: 8px; box-shadow: var(--shadow-md); position: relative; overflow: hidden; }
.title { color: var(--color-text); font-size: clamp(1.8rem, 5vw, 2.5rem); margin-bottom: 1rem; font-family: var(--font-ui); text-transform: uppercase; letter-spacing: 0.02em; }
.documents-actions { display: flex; justify-content: space-between; gap: 1rem; margin: 0 auto 1rem; flex-wrap: wrap; flex-direction: column; }
.search-controls { display: flex; flex-wrap: wrap; align-items: center; gap: 0.75rem; flex: 1; }
.search-container { position: relative; flex: 1; min-width: 220px; }
.filter-row { display: flex; gap: 0.5rem; flex-wrap: wrap; }
